const tanggalTanam = global.get('tanggal_tanam');
if (!tanggalTanam) {
    node.status({fill:'red',shape:'ring',text:'Tanggal tanam belum ada'});
    return null;
}

const bagian = String(tanggalTanam).substring(0,10).split('-').map(Number);
if (bagian.length !== 3 || bagian.some(v => !Number.isFinite(v))) {
    node.error('Format tanggal tanam harus YYYY-MM-DD');
    return null;
}

const sekarang = new Date();
sekarang.setHours(0,0,0,0);
const mulai = new Date(bagian[0], bagian[1] - 1, bagian[2]);
let hariKe = Math.floor((sekarang - mulai) / 86400000) + 1;
if (hariKe < 1) hariKe = 0;

let fase = 'belum_dimulai';
let status = 'belum_dimulai';
let tdsMin = 0;
let tdsMax = 0;
let targetTds = 0;

if (hariKe >= 1 && hariKe <= 6) {
    fase = 'penyemaian'; status = 'aktif';
} else if (hariKe >= 7 && hariKe <= 11) {
    fase = 'awal_nutrisi'; status = 'aktif';
    tdsMin = 285; tdsMax = 300; targetTds = 300;
} else if (hariKe >= 12 && hariKe <= 26) {
    fase = 'pertumbuhan'; status = 'aktif';
    tdsMin = 500; tdsMax = 600; targetTds = 550;
} else if (hariKe >= 27) {
    fase = 'menjelang_panen'; status = 'aktif';
    tdsMin = 775; tdsMax = 800; targetTds = 800;
}

const phMin = 5.5;
const phMax = 6.5;
const targetPh = 6.0;

const systemConfig = {
    hari_ke: hariKe, fase,
    tanggal_tanam: String(tanggalTanam).substring(0,10),
    status_sistem: status
};
const tdsConfig = {tds_min:tdsMin, tds_max:tdsMax, target_tds:targetTds};
const phConfig = {ph_min:phMin, ph_max:phMax, target_ph:targetPh};

flow.set('config_system', systemConfig);
flow.set('config_tds', tdsConfig);
flow.set('config_ph', phConfig);

node.status({fill:'blue',shape:'dot',text:`Hari ${hariKe} | ${fase}`});
return [[
    {topic:'sumenep/hydroponic/system/config', payload:JSON.stringify(systemConfig)},
    {topic:'sumenep/hydroponic/config/tds', payload:JSON.stringify(tdsConfig)},
    {topic:'sumenep/hydroponic/config/ph', payload:JSON.stringify(phConfig)}
]];

const data = msg.payload;
if (!data || typeof data !== 'object') return null;

if ('tds_ppm' in data) flow.set('sensor_tds', {sensor:'tds', value:data.tds_ppm, data, timestamp:Date.now()});
if ('temperature_c' in data) flow.set('sensor_temperature', {sensor:'temperature', value:data.temperature_c, data, timestamp:Date.now()});
if ('distance_cm' in data) flow.set('sensor_distance', {sensor:'distance', value:data.distance_cm, data, timestamp:Date.now()});
if ('light_lux' in data) flow.set('sensor_light', {sensor:'light', value:data.light_lux, data, timestamp:Date.now()});
if ('turbidity_ntu' in data) flow.set('sensor_turbidity', {sensor:'turbidity', value:data.turbidity_ntu, data, timestamp:Date.now()});
if ('ph' in data) flow.set('sensor_ph', {sensor:'ph', value:data.ph, data, timestamp:Date.now()});

node.status({fill:'green',shape:'dot',text:`TDS:${data.tds_ppm} | pH:${data.ph} | T:${data.temperature_c}`});

const msgTds = { ...msg, sensor: 'tds', value: data.tds_ppm, payload: data };
const msgPh = { ...msg, sensor: 'ph', value: data.ph, payload: data };

node.send([[msg, msgTds, msgPh]]);
return null;

if (msg.sensor !== 'tds') return null;
const ppm = Number(msg.value);
const cfg = flow.get('config_tds');
if (!Number.isFinite(ppm) || !cfg) {
    node.status({fill:'red',shape:'ring',text:'Data/config TDS belum ada'});
    return null;
}

const DOSE_MS = 2000;
const SETTLE_MS = 60000;
const now = Date.now();
const busyUntil = context.get('busy_until') || 0;
const send = (relay,state) => node.send({topic:'sumenep/hydroponic/control',payload:JSON.stringify({relay,state})});

if (now < busyUntil) {
    node.status({fill:'blue',shape:'dot',text:`Tunggu ${Math.ceil((busyUntil-now)/1000)}s`});
    return null;
}
if (cfg.target_tds <= 0 || ppm >= cfg.target_tds) {
    send(1,false); send(2,false);
    node.status({fill:'green',shape:'dot',text:`${ppm.toFixed(1)} ppm | target ${cfg.target_tds}`});
    return null;
}

context.set('busy_until', now + DOSE_MS + SETTLE_MS);
send(1,true); send(2,true);
node.status({fill:'yellow',shape:'dot',text:`Dosis nutrisi | ${ppm.toFixed(1)} ppm`});
setTimeout(() => { send(1,false); send(2,false); }, DOSE_MS);
setTimeout(() => node.send({topic:'sumenep/hydroponic/control',payload:'{"sensor":"tds"}'}), DOSE_MS + SETTLE_MS);
return null;

if (msg.sensor !== 'ph') return null;
const ph = Number(msg.value);
const cfg = flow.get('config_ph');
if (!Number.isFinite(ph) || !cfg) {
    node.status({fill:'red',shape:'ring',text:'Data/config pH belum ada'});
    return null;
}

const DOSE_MS = 2000;
const SETTLE_MS = 60000;
const now = Date.now();
const busyUntil = context.get('busy_until') || 0;
const send = (relay,state) => node.send({topic:'sumenep/hydroponic/control',payload:JSON.stringify({relay,state})});

if (now < busyUntil) {
    node.status({fill:'blue',shape:'dot',text:`pH ${ph.toFixed(2)} | tunggu ${Math.ceil((busyUntil-now)/1000)}s`});
    return null;
}
if (ph < cfg.ph_min) {
    context.set('busy_until', now + DOSE_MS + SETTLE_MS);
    send(4,false); send(3,true);
    node.status({fill:'yellow',shape:'dot',text:`pH ${ph.toFixed(2)} | pH Up`});
    setTimeout(() => send(3,false), DOSE_MS);
} else if (ph > cfg.ph_max) {
    context.set('busy_until', now + DOSE_MS + SETTLE_MS);
    send(3,false); send(4,true);
    node.status({fill:'yellow',shape:'dot',text:`pH ${ph.toFixed(2)} | pH Down`});
    setTimeout(() => send(4,false), DOSE_MS);
} else {
    context.set('busy_until', 0);
    send(3,false); send(4,false);
    node.status({fill:'green',shape:'dot',text:`pH ${ph.toFixed(2)} normal`});
}
return null;
